parameters.jsCode:
const booking = $('Split Bookings').item.json.booking;
const raw = $input.first().json || {};
let text = raw.output_text || raw.output?.[0]?.content?.[0]?.text || raw.content?.[0]?.text || '';
let brief = null;
let error = null;
try {
  brief = JSON.parse(text);
} catch (e) {
  error = raw.error ? JSON.stringify(raw.error).slice(0, 900) : 'GPT response was missing or invalid JSON';
}
const valid = brief && typeof brief.owner_brief === 'string' && Array.isArray(brief.questions_to_ask);
return [{ json: { booking_id: booking.id, ok: !!valid, ai_brief: valid ? brief : null, ai_brief_error: valid ? null : error } }];
